package java.util.function;
public interface BiPredicate<T,U> { boolean test(T t,U u); default BiPredicate<T,U> and(final BiPredicate<? super T,? super U> p){java.util.Objects.requireNonNull(p);return new BiPredicate<T,U>(){public boolean test(T t,U u){return BiPredicate.this.test(t,u)&&p.test(t,u);}};} default BiPredicate<T,U> or(final BiPredicate<? super T,? super U> p){java.util.Objects.requireNonNull(p);return new BiPredicate<T,U>(){public boolean test(T t,U u){return BiPredicate.this.test(t,u)||p.test(t,u);}};} default BiPredicate<T,U> negate(){return new BiPredicate<T,U>(){public boolean test(T t,U u){return !BiPredicate.this.test(t,u);}};} }
